// ── ht-sweep-armed ── S2: decide whether this tick may scan the keyspace AT ALL ──────────────────
//
// FINDING #6 (rev5): the kill-switch was only consulted inside `ht-sweep-census`, which runs AFTER
// `ht-sweep-keys`. So a dark-shipped feature — the intended state between the S4 promote and the flip,
// potentially weeks — still paid the full cost every 30 seconds: a `KEYS ht:active:*` scan plus a GET per
// matching key, on the SHARED PRODUCTION redis, to produce a census that was then discarded.
//
// That cost is not incidental. `KEYS` is O(total keyspace) on a single-threaded server (reviewer R6), so
// it is a function of the whole prod keyspace — message lists, per-contact concurrency locks, the ttl:1
// rate-limit counters — and is independent of how many contacts are in the pilot. Paying it for a feature
// that is switched OFF is the worst version of the trade.
//
// This node gates the scan on the kill-switch. `ht-sweep-census` keeps its OWN check as defence in depth
// (it also covers the per-candidate reasons), so removing this node degrades cost, never safety.
//
// FAIL-CLOSED IN THE COST DIRECTION TOO: a config read that FAILS does not scan. Same reasoning as the
// allowlist fix — "I could not read the kill-switch" is not permission to hit prod redis every 30 s.
//
// ⚠️ UAC IMPACT — HT-11's assertions change. With the kill-switch off, `ht-sweep-keys` and
// `ht-sweep-census` no longer appear in runData at all, so HT-11 can no longer assert
// "census shows skip_reason: kill-switch-off". Assert instead: `ht-armed?` took output 1, `ht-sweep-idle`
// ran, and `ht-sweep-keys` / `ht-sweep-census` / `ht-findcontact` are ABSENT from runData — which is a
// strictly stronger statement (nothing was even read) and is asserted on node presence, not a status.

function readNode(nodeName, prop) {
  let n;
  try { n = $(nodeName); } catch (e) { return { ok: false, why: nodeName + ' is unreachable' }; }
  if (!n) return { ok: false, why: nodeName + ' resolved to nothing' };
  if (n.isExecuted === false) return { ok: false, why: nodeName + ' did not execute' };
  let f;
  try { f = n.first(); } catch (e) { return { ok: false, why: nodeName + ' produced no item' }; }
  if (!f || !f.json) return { ok: false, why: nodeName + ' produced no json' };
  if (!Object.prototype.hasOwnProperty.call(f.json, prop)) {
    return { ok: false, why: nodeName + " carried no '" + prop + "' property (propertyName drift?)" };
  }
  return { ok: true, value: f.json[prop] };
}

const r = readNode('ht-sweep-enabled', 'ht_enabled');
const ht_enabled = r.ok && r.value !== null && r.value !== undefined && String(r.value).trim() === '1';
const ht_armed = ht_enabled;

return [{
  json: {
    ht_enabled,
    ht_armed,
    ht_not_armed_because: ht_armed ? null : (r.ok ? 'kill-switch-off' : 'config-read-failure: ' + r.why),
    // what this tick declined to do, so a quiet tick is legible in runData rather than just absent
    ht_skipped_work: ht_armed ? null : 'KEYS scan + per-key GETs on the shared redis',
  },
}];

// ── ht-sweep-census ── S2 sweeper: the OBSERVABLE decision record for one tick ──────────────────
//
// WHY THIS IS A SEPARATE NODE FROM THE FAN-OUT. A Code node that emits 0 items ends its branch —
// which is the correct runtime behaviour for a quiet tick, and a terrible instrument: "no
// downstream nodes ran" is indistinguishable from "the node never looked at anything"
// (LESSONS §61b — never let empty checker output mean PASS; print the compared population).
// So this node ALWAYS emits exactly ONE item carrying the full census — scanned count, cutoff,
// every candidate with its age and its skip reason — and `ht-sweep-fanout` turns that into 0..N
// action items. HT-10/11/12 assert against THIS item, not against downstream absence alone.
//
// INPUT. One item from `ht-sweep-keys` (Redis `keys`, getValues = true), whose json is a MAP of
// `<prefix>active:<contact id>` -> stamp-in-ms-as-string. Non-matching keys are ignored and
// counted, never guessed at.
//
// NOTE ON `keys`. The native Redis node has no sorted-set support at all (operations are
// delete/get/incr/info/keys/llen/pop/publish/push/set), so the plan's ZSET contract is implemented
// as one string key per contact. `keys` is O(keyspace); see the plan's deviation note.
//
// FAIL-CLOSED: kill-switch off ⇒ zero candidates eligible, with the reason recorded on every row.

const DEFAULT_TIMEOUT_SEC = 300;
const FLOOR_TIMEOUT_SEC = 60;
const KEY_INFIX = 'active:';

// A config read has THREE outcomes, not two. Collapsing them is finding #1 (rev5): `readNode` used to
// return `undefined` both when the READ FAILED (node renamed, never executed, `propertyName` drift) and
// when the VALUE was legitimately absent (redis GET on a missing key returns null). `parsePilot(undefined)`
// is `[]`, and an empty allowlist means EVERYONE — so if only the pilot leg broke while `enabled` still
// read "1", the pilot phase acted on every real contact. Measured: contact 999999 got
// `ht_should_act: true` with the pilot node removed.
//
// The kill-switch already failed closed. The allowlist must too, and it is the one whose failure direction
// is a real customer receiving a message. Note the asymmetry that has to be preserved: an empty-string
// VALUE still means everyone — that is the announce flip, and it is deliberate — while a failed READ
// means "I do not know who is in the allowlist", which is not a permission to act.
//   { ok: true,  value }  the node ran and carried the property (value may legitimately be null)
//   { ok: false, why   }  the read itself failed — never treat this as "no allowlist"
function readNode(nodeName, prop) {
  let n;
  try { n = $(nodeName); } catch (e) { return { ok: false, why: nodeName + ' is unreachable' }; }
  if (!n) return { ok: false, why: nodeName + ' resolved to nothing' };
  if (n.isExecuted === false) return { ok: false, why: nodeName + ' did not execute' };
  let f;
  try { f = n.first(); } catch (e) { return { ok: false, why: nodeName + ' produced no item' }; }
  if (!f || !f.json) return { ok: false, why: nodeName + ' produced no json' };
  if (!Object.prototype.hasOwnProperty.call(f.json, prop)) {
    return { ok: false, why: nodeName + " carried no '" + prop + "' property (propertyName drift?)" };
  }
  return { ok: true, value: f.json[prop] };
}

function parseEnabled(v) {
  return v !== null && v !== undefined && String(v).trim() === '1';
}

function parseTimeoutSec(v) {
  const n = Number(String(v == null ? '' : v).trim());
  if (!Number.isFinite(n) || n <= 0) return DEFAULT_TIMEOUT_SEC;
  return Math.max(FLOOR_TIMEOUT_SEC, Math.floor(n));
}

function parsePilot(v) {
  if (v === null || v === undefined) return [];
  const raw = Array.isArray(v) ? v : String(v).split(',');
  return raw.map((x) => String(x).trim()).filter((x) => x.length > 0);
}

const rEnabled = readNode('ht-sweep-enabled', 'ht_enabled');
const rTimeout = readNode('ht-sweep-timeout', 'ht_timeout_sec');
const rPilot = readNode('ht-sweep-pilot', 'ht_pilot');
const ht_config_read_failures = [rEnabled, rTimeout, rPilot].filter((r) => !r.ok).map((r) => r.why);

const ht_enabled = rEnabled.ok && parseEnabled(rEnabled.value);
const ht_timeout_sec = parseTimeoutSec(rTimeout.ok ? rTimeout.value : undefined);
const ht_pilot = rPilot.ok ? parsePilot(rPilot.value) : [];
const ht_pilot_active = ht_pilot.length > 0;

const NOW = typeof $now !== 'undefined' && $now && typeof $now.toMillis === 'function'
  ? $now.toMillis()
  : Date.now();
const cutoff_ms = NOW - ht_timeout_sec * 1000;

const raw = ($input.all()[0] && $input.all()[0].json) || {};
const candidates = [];
let malformed = 0;

for (const key of Object.keys(raw)) {
  const at = key.lastIndexOf(KEY_INFIX);
  if (at === -1) { malformed++; continue; }
  const contact_id = key.slice(at + KEY_INFIX.length).trim();
  if (!contact_id) { malformed++; continue; }
  const scoreRaw = raw[key];
  const score_ms = Number(String(scoreRaw == null ? '' : scoreRaw).trim());
  if (!Number.isFinite(score_ms)) {
    // NOT NEGOTIABLE: a stamp we cannot parse is not quietly treated as "infinitely old" — that would
    // clear a live intervention on a typo. Recorded and skipped, so the tick stays visible and inert.
    // Known residual (rev5): such a stamp is therefore never reaped either, because the recheck reads the
    // same garbage and answers skip-vanished. Recorded in the manifest rather than half-fixed here.
    candidates.push({
      contact_id, key, score_ms: null, age_ms: null,
      expired: false, eligible: false, skip_reason: 'unparseable-stamp',
    });
    continue;
  }
  // A zero / negative stamp IS parseable — epoch 0, i.e. infinitely old. It used to share the
  // unparseable branch, which made it un-reapable forever while `ht-arm` treats 0 as a perfectly valid
  // stamp: the two nodes disagreed about the same value (finding #5). A garbage-but-numeric stamp must
  // not immortalise the flag, so it is expired and reapable. The flag check still gates the notice and
  // the recheck still reads the same value, so this authorises nothing that any other expired stamp
  // would not.
  const expired = score_ms <= cutoff_ms;
  let skip_reason = null;
  if (ht_config_read_failures.length) skip_reason = 'config-read-failure';
  else if (!ht_enabled) skip_reason = 'kill-switch-off';
  else if (ht_pilot_active && ht_pilot.indexOf(contact_id) === -1) skip_reason = 'not-in-pilot-allowlist';
  else if (!expired) skip_reason = 'not-expired';
  candidates.push({
    contact_id, key, score_ms, age_ms: NOW - score_ms,
    expired, eligible: skip_reason === null, skip_reason,
  });
}

return [{
  json: {
    ht_enabled,
    ht_timeout_sec,
    ht_pilot,
    ht_pilot_active,
    ht_config_read_failures,
    now_ms: NOW,
    cutoff_ms,
    scanned: Object.keys(raw).length,
    malformed_keys: malformed,
    candidates,
    eligible_count: candidates.filter((c) => c.eligible).length,
    skipped_count: candidates.filter((c) => !c.eligible).length,
  },
}];

// ── ht-sweep-fanout ── S2 sweeper: turn the census into 0..N per-contact action items ───────────
//
// Emits ONE item per ELIGIBLE candidate and nothing else. Zero items is the normal case and ends
// the branch, which is why the census (always exactly one item) is the thing assertions read.
// Deliberately dumb: every decision already happened in `ht-sweep-census`, so a mutation of the
// expiry/allowlist logic shows up in exactly one place.

const c = ($input.all()[0] && $input.all()[0].json) || {};
const cutoff_ms = c.cutoff_ms;
const now_ms = c.now_ms;

return (c.candidates || [])
  .filter((x) => x && x.eligible === true)
  .map((x) => ({
    json: {
      contact_id: x.contact_id,
      key: x.key,
      score_ms: x.score_ms,
      age_ms: x.age_ms,
      cutoff_ms,
      now_ms,
      ht_timeout_sec: c.ht_timeout_sec,
    },
  }));

// ── ht-carry-contact ── S2: pair each expired candidate with its contact lookup ─────────────────
//
// EXISTS BECAUSE OF F-RECHECK (tester, 2026-08-12). `ht-recheck-stamp`'s key expression reads
// `$json.contact_id`, but its former upstream `ht-findcontact` emits a respond.io CONTACT — whose id
// field is `id`, never `contact_id`. Every recheck missed, `ht-classify` always answered
// `skip-vanished`, and the clear/notify/forget path was structurally unreachable: flags never cleared.
// Failed safe, but inert. `assert-built.py` C9 is the gate that now closes that class.
//
// REWRITTEN rev3 for reviewer R2 + R3, which turned out to be one defect wearing two hats:
//
//   R2 (fail-open guard). `if (fetchedId && fetchedId !== contact_id) throw` demanded a CONTRADICTION,
//   not an identification: a payload with no `id` short-circuited the refusal and flowed on to
//   `clear-and-notify`, authorising a flag write and a WhatsApp notice off a contact never positively
//   identified. Measured. The header claimed the node "owns the mis-attribution refusal", which was
//   stricter than the mechanism delivered — LESSONS §70b, inverted.
//
//   R3 (stamp leak on not-found). On a hard not-found the findcontact sub returns ZERO items. Under the
//   old INDEX-ALIGNED pairing that made this node THROW — so a single deleted or unknown contact did not
//   merely leak its stamp, it **wedged the sweeper permanently**: every subsequent tick errored, and
//   because the stamp is never removed the condition never cleared itself. Measured. The literal R2 fix
//   (throw on an id-less payload) has the identical shape, so fixing R2 alone would have hardened a
//   permanent-outage path.
//
// So pairing is now BY IDENTITY, not by index, with three outcomes and no unreachable arm:
//
//   paired            the lookup returned exactly this contact          → carry on to the recheck
//   lookup_missing    no lookup came back for this candidate            → `forget-unknown`: the stamp is
//                     (deleted contact, hard not-found, zero items)       REAPED, with ZERO flag write
//                                                                         and ZERO notice
//   THROW             a lookup came back for a contact NOBODY asked for → refuse the whole tick
//
// R2 is satisfied more strongly than by throwing: an unidentified payload cannot reach
// `clear-and-notify` at all, and the tick survives. R3's reaper falls out for free — `forget-unknown`
// routes to the existing `ht-forget-silent`, so no new wiring and no new egress surface. That also stops
// feeding D1's `KEYS ht:active:*` cost, which R6 raises to a pre-ACTIVATION measurement.
//
// PROMOTE-SAFE. At S4 `ht-findcontact` becomes the real `executeWorkflow` call to
// `sorento-sub-respond-findcontact-respond`, which returns the same raw shape (`id`, no `contact_id`) and
// zero items on a miss. Identity pairing needs no `alwaysOutputData` and tolerates missing, extra or
// reordered items, so it behaves the same on both. **S4 must promote this node** — without it the
// promoted sweeper is the dead feature F-RECHECK described.
//
// NO `.first()`: a tick can carry several contacts and `.first()` is silently item 0 for every row
// (assert-built.py C9 forbids it inside the per-item region).

function nodeAll(name) {
  let n;
  try { n = $(name); } catch (e) {
    throw new Error('ht-carry-contact: ' + name + ' is unreachable — refusing to pair');
  }
  if (!n || n.isExecuted === false) {
    throw new Error('ht-carry-contact: ' + name + ' did not execute — refusing to pair');
  }
  return n.all();
}

const candidates = nodeAll('ht-sweep-fanout');
const lookups = $input.all();

// Index the lookups by the id they positively identify. An item with no usable id identifies nothing,
// so it is counted and never matched — it can only ever produce a `lookup_missing` row.
const byId = new Map();
let unidentifiable = 0;
for (const it of lookups) {
  const j = it.json || {};
  const id = j.id === null || j.id === undefined ? '' : String(j.id).trim();
  if (!id) { unidentifiable++; continue; }
  if (byId.has(id)) {
    throw new Error(
      'ht-carry-contact: two lookups both claim contact ' + id + ' — ambiguous, refusing to pair. ' +
      'A redis stamp key is unique per contact, so this should be unreachable.'
    );
  }
  byId.set(id, j);
}

const wanted = new Set();
for (const c of candidates) {
  const cid = String((c.json || {}).contact_id == null ? '' : (c.json || {}).contact_id).trim();
  if (!cid) throw new Error('ht-carry-contact: candidate carries no contact_id — refusing to pair');
  wanted.add(cid);
}
// A contact nobody asked for is DROPPED, not thrown on (finding #2, rev5).
//
// Throwing here refused the ENTIRE tick, and the stamps survive an error — so a single mis-attributed
// lookup recurred every 30 s forever and wedged the sweeper instance-wide. That is the exact R3 outage
// shape this file's own header documents, reintroduced on the adjacent branch: the realistic trigger is a
// respond.io CONTACT MERGE, where looking up a deleted id returns the surviving contact's id, and it is
// permanent by construction because nothing ever removes the stamp that keeps re-triggering it.
//
// Dropping is also the semantically correct answer, not merely the safe one: if a lookup for candidate X
// comes back as some other contact, then X is gone (merged or deleted). Its candidate now pairs with
// nobody, so the existing `forget-unknown` path reaps X's stamp with ZERO egress — which is precisely
// what should happen to a merged-away contact. No key is ever derived from the stranger.
const strangers = [];
for (const id of Array.from(byId.keys())) {
  if (!wanted.has(id)) {
    strangers.push(id);
    byId.delete(id);
  }
}

return candidates.map((c, i) => {
  const src = c.json || {};
  const contact_id = String(src.contact_id).trim();
  const contact = byId.has(contact_id) ? byId.get(contact_id) : null;
  return {
    json: {
      // `contact_id` is what `ht-recheck-stamp`'s key expression reads. It is always the CANDIDATE's
      // id — the contact we decided to expire — never whatever a lookup happened to return.
      contact_id,
      contact,
      lookup_missing: contact === null,
      lookup_missing_reason: contact === null
        ? (lookups.length === 0
            ? 'the contact lookup returned no items at all (hard not-found)'
            : (strangers.length
                ? 'no lookup item identified this contact; the tick returned contact(s) nobody asked ' +
                  'for (' + strangers.join(',') + ') — consistent with a merged or deleted contact'
                : 'no lookup item positively identified this contact (' + unidentifiable +
                  ' unidentifiable item(s) in this tick)'))
        : null,
      // surfaced per row so a merge shows up in runData instead of being inferred from a reap
      lookup_strangers: strangers,
      key: src.key === undefined ? null : src.key,
      score_ms: src.score_ms === undefined ? null : src.score_ms,
      age_ms: src.age_ms === undefined ? null : src.age_ms,
      cutoff_ms: src.cutoff_ms === undefined ? null : src.cutoff_ms,
      now_ms: src.now_ms === undefined ? null : src.now_ms,
      ht_timeout_sec: src.ht_timeout_sec === undefined ? null : src.ht_timeout_sec,
    },
    pairedItem: { item: i },
  };
});

// ── ht-classify ── S2 sweeper: decide, per expired contact, what may be done to it ──────────────
//
// This is the only node that authorises the two egress actions (`is_human_intervened: false` write
// and the timeout WhatsApp notice), so it is written to REFUSE rather than guess.
//
// THREE OUTCOMES, and they are not the same shape as "true/false":
//   clear-and-notify  the flag is still true and the stamp has not moved  → write + notify + forget
//   forget-silent     the flag is already false (a human closed manually) → forget the stamp, ZERO
//                     sends. This is the ghost-message gate (HT-9).
//   forget-unknown    the contact lookup returned nothing for this        → forget the stamp, ZERO
//                     candidate (deleted / unknown contact)                sends, ZERO flag write.
//                     Added rev3 for reviewer R3: without it a hard not-found either leaked the stamp
//                     forever or — under the old index-aligned pairing — THREW, wedging the sweeper
//                     permanently. Routes to the existing `ht-forget-silent`, so no new wiring.
//   skip-*            the stamp vanished or moved forward under us        → touch nothing at all
//
// WHY THE RE-READ. Plan §S2.5 lists a stamp re-read as an OPTIONAL tightening. It is implemented
// (and recorded as an addition in the plan) because the failure it prevents is customer-visible:
// a human replying while the tick is in flight would otherwise have their intervention cleared and
// the contact told "our team seems to be away" mid-conversation. One redis GET, one predicate.
//
// ABSENT vs PRESENT-BUT-EMPTY (LESSONS §64). Two different malformed shapes, two different
// answers, neither of them a silent pass:
//   - `custom_fields` not an array          → THROW. The payload is not a respond.io contact; a
//                                             hand-built fixture that omits it must ERROR, not pass
//                                             (UAC HT-FP4 exists to prove this).
//   - `is_human_intervened` absent from the array → the contact genuinely has no such field ⇒
//                                             treat as not-intervened ⇒ forget-silent.
//   - value present but an unrecognised encoding   → THROW. respond.io stores this as the STRING
//                                             "true"/"false" (verified against a real FIND_CONTACT
//                                             payload, execution 12166204); anything else means the
//                                             contract moved and guessing would clear real flags.
//
// WHY THE CANDIDATES ARE READ BY NAME AND NOT FROM `$input`. The node immediately upstream is
// `ht-recheck-stamp`, a Redis `get` — and the Redis node's `get` emits a FRESH item (`{json:{}}` plus
// the one property it was asked for) instead of passing its input through. So `$input.all()[i].json`
// here is `{ht_recheck_ms: …}` with NO contact_id and NO cutoff_ms. Reading the candidates from
// `$input` would be a textbook §63 wrong-object read: sound logic, correct-looking assertions,
// pointed at the wrong payload. (It was written that way first and caught by re-deriving the wiring;
// the offline harness had been stubbing `$input` with the fan-out items, so the suite would have gone
// green against a body that throws in production.) Only `push`/`set`/`delete` are passthrough.
//
// INDEX ALIGNMENT. `ht-carry-contact` and `ht-recheck-stamp` each run once per fan-out item, so both
// are index-aligned with each other. That is asserted, not assumed.
//
// The candidate and its contact arrive already paired from `ht-carry-contact` (added for F-RECHECK),
// which also owns the mis-attribution refusal — deliberately upstream of here, because the redis key
// `ht-recheck-stamp` reads is derived BEFORE this node runs, so a guard sitting here would fire after
// the wrong key had already been read.

const TRUEY = ['true', '1', 'yes'];
const FALSEY = ['false', '0', 'no', ''];

function nodeAll(nodeName) {
  let n;
  try { n = $(nodeName); } catch (e) {
    throw new Error(`ht-classify: required node ${nodeName} is unreachable — refusing to classify`);
  }
  if (!n || n.isExecuted === false) {
    throw new Error(`ht-classify: required node ${nodeName} did not execute — refusing to classify`);
  }
  return n.all();
}

function readFlag(contact) {
  const cf = contact ? contact.custom_fields : undefined;
  if (!Array.isArray(cf)) {
    throw new Error(
      'ht-classify: contact payload has no custom_fields array — not a respond.io contact. ' +
      'Refusing to classify (a fixture missing custom_fields must fail loudly, not pass).'
    );
  }
  const row = cf.find((x) => x && x.name === 'is_human_intervened');
  if (!row) return { present: false, raw: null, flag: false };
  const raw = row.value;
  if (raw === null || raw === undefined) return { present: true, raw, flag: false };
  if (typeof raw === 'boolean') return { present: true, raw, flag: raw };
  const s = String(raw).trim().toLowerCase();
  if (TRUEY.indexOf(s) !== -1) return { present: true, raw, flag: true };
  if (FALSEY.indexOf(s) !== -1) return { present: true, raw, flag: false };
  throw new Error(
    `ht-classify: is_human_intervened has an unrecognised encoding ${JSON.stringify(raw)} — ` +
    'refusing to guess. respond.io stores this as the string "true"/"false".'
  );
}

const items = nodeAll('ht-carry-contact');
const rechecks = nodeAll('ht-recheck-stamp');

if (rechecks.length !== items.length) {
  throw new Error(
    `ht-classify: index misalignment — ${items.length} paired candidates but ` +
    `${rechecks.length} stamp re-reads. Refusing to classify mis-attributed rows.`
  );
}

return items.map((it, i) => {
  const src = it.json || {};
  const contact = src.contact === undefined ? null : src.contact;
  const contact_id = String(src.contact_id == null ? '' : src.contact_id).trim();

  const rj = (rechecks[i] && rechecks[i].json) || {};
  const rescoreRaw = rj.ht_recheck_ms;
  // `Number('') === 0`, so an ABSENT stamp used to be recorded as a re-read of epoch 0 rather than as no
  // re-read at all (finding #5b) — a skip-vanished row claimed `recheck_ms: 0`, which reads as a real
  // measurement. Track absence separately so the reported value can be null.
  const rescoreAbsent = rescoreRaw === null || rescoreRaw === undefined ||
                        String(rescoreRaw).trim() === '';
  const rescore = rescoreAbsent ? NaN : Number(String(rescoreRaw).trim());
  const cutoff_ms = Number(src.cutoff_ms);

  let action;
  let reason;
  if (rescoreAbsent) {
    action = 'skip-vanished';
    reason = 'stamp disappeared between the census and now — someone else already handled it';
  } else if (!Number.isFinite(rescore)) {
    action = 'skip-vanished';
    reason = 'stamp re-read is unparseable — refusing to act on it';
  } else if (!Number.isFinite(cutoff_ms)) {
    throw new Error('ht-classify: candidate carries no numeric cutoff_ms — refusing to classify');
  } else if (rescore > cutoff_ms) {
    action = 'skip-refreshed';
    reason = 'a human replied after the cutoff while this tick was in flight';
  } else if (src.lookup_missing === true) {
    // No positively-identified contact came back for this candidate. Reap the stamp; authorise nothing.
    // Deliberately NOT a throw: a throw here means one deleted contact errors every future tick, and
    // because the stamp survives the error the condition never clears itself (reviewer R2+R3).
    action = 'forget-unknown';
    reason = src.lookup_missing_reason || 'the contact lookup returned nothing for this candidate';
  } else {
    const f = readFlag(contact);
    if (f.flag) {
      action = 'clear-and-notify';
      reason = 'expired and still flagged as human-intervened';
    } else {
      action = 'forget-silent';
      reason = f.present
        ? 'flag already false — closed manually, nothing to announce'
        : 'contact has no is_human_intervened field — nothing to clear';
    }
  }

  const flagInfo = action === 'clear-and-notify' || action === 'forget-silent'
    ? readFlag(contact)
    : { present: null, raw: null, flag: null };   // forget-unknown has no contact to read

  return {
    json: {
      contact_id,
      action,
      reason,
      is_skip: action.indexOf('skip') === 0,
      lookup_missing: src.lookup_missing === true,
      flag: flagInfo.flag,
      flag_present: flagInfo.present,
      flag_raw: flagInfo.raw,
      score_ms: src.score_ms === undefined ? null : src.score_ms,
      recheck_ms: Number.isFinite(rescore) ? rescore : null,
      cutoff_ms: Number.isFinite(cutoff_ms) ? cutoff_ms : null,
      age_ms: src.age_ms === undefined ? null : src.age_ms,
      key: src.key === undefined ? null : src.key,
      ht_timeout_sec: src.ht_timeout_sec === undefined ? null : src.ht_timeout_sec,
      ht_timeout_notice:
        'Our team seems to be away at the moment. Our AI assistant is back to assist you.',
    },
    pairedItem: { item: i },
  };
});

// ── ht-carry-clear ── S2: re-attach the fields the DELETE and the SEND need, across the egress node ──
//
// EXISTS BECAUSE OF REVIEWER R1 — F-RECHECK's class recurring one node DOWNSTREAM, on the promote path,
// invisible to every gate that already exists.
//
// `ht-forget.key` reads `$json.contact_id` and `ht-timeout-notice` reads `$json.contact_id` +
// `$json.ht_timeout_notice`. On the BUILD those resolve, because `ht-clear-flag` is a Code stand-in that
// deliberately re-forwards both and `ht-egress-log` is a redis `push` (a passthrough). At S4
// `ht-clear-flag` becomes the real respondio CONTACTS/UPDATE_CONTACT node, whose real output — measured
// on live `respond-send-user`, execution 12146305 — is exactly:
//
//     {"contactId": 423755030}
//
// `contactId` only. No `contact_id`, no notice text. So on live, unfixed: `ht-forget` would delete
// `ht:active:` (empty suffix) and miss, and `ht-timeout-notice` would fire with an EMPTY RECIPIENT and an
// EMPTY BODY — the customer-facing notice, the entire point of the feature, malformed on a real send path.
//
// This is LESSONS §65 verbatim: before promoting a hunk verified on the clone, diff the clone's INBOUND
// EDGES against live's, because a substituted upstream changes what `$json` means without changing a line
// of the node you tested. `assert-built.py` C9 could not see it — C9 resolved against the STAND-IN's
// fields, which are correct. C9 is now extended (the promote-shape pass) to resolve against each
// converted node's REAL recorded output, and that pass was shown RED on the rev2 graph before this node
// existed.
//
// WHY MATCH BY IDENTITY RATHER THAN INDEX. `ht-classify` emits a row for EVERY candidate — skips,
// forget-silent, forget-unknown and clear-and-notify alike — while only the clear-and-notify subset
// reaches here. So index alignment against `$('ht-classify')` is simply wrong, and the reviewer's
// suggested `.item` paired-item walk is unavailable in a runOnceForAllItems node (and would be a lineage
// walk through the egress node). Matching on the id the egress node itself reports is exact, needs no
// lineage, and works identically on the stand-in and the real node — both emit `contactId`.
//
// It also RE-CHECKS AUTHORISATION. The notice may only fire for a row `ht-classify` decided was
// `clear-and-notify`; anything else here means the graph is not the graph we think it is, and it is
// refused rather than sent. Cheap, and it is the last gate before a real WhatsApp send at S4.

function nodeAll(name) {
  let n;
  try { n = $(name); } catch (e) {
    throw new Error('ht-carry-clear: ' + name + ' is unreachable — refusing to send or delete');
  }
  if (!n || n.isExecuted === false) {
    throw new Error('ht-carry-clear: ' + name + ' did not execute — refusing to send or delete');
  }
  return n.all();
}

const decisions = new Map();
for (const it of nodeAll('ht-classify')) {
  const j = it.json || {};
  const cid = String(j.contact_id == null ? '' : j.contact_id).trim();
  if (!cid) continue;
  if (decisions.has(cid)) {
    throw new Error('ht-carry-clear: two decisions for contact ' + cid + ' — ambiguous, refusing');
  }
  decisions.set(cid, j);
}

return $input.all().map((it, i) => {
  const j = it.json || {};
  // The real respondio node reports `contactId`; the stand-in reports both. Read the real field first so
  // this node is not quietly depending on the stand-in's extra one.
  const raw = j.contactId !== undefined && j.contactId !== null ? j.contactId : j.contact_id;
  const contact_id = String(raw == null ? '' : raw).trim();
  if (!contact_id) {
    throw new Error(
      'ht-carry-clear: the contact update returned no contactId, so the contact whose flag was just ' +
      'cleared cannot be identified. Refusing to derive a redis DELETE key or send a notice.'
    );
  }
  const d = decisions.get(contact_id);
  if (!d) {
    throw new Error(
      'ht-carry-clear: no ht-classify decision for contact ' + contact_id + ' — refusing to send a ' +
      'notice to a contact this tick never authorised.'
    );
  }
  if (d.action !== 'clear-and-notify') {
    throw new Error(
      'ht-carry-clear: contact ' + contact_id + ' reached the notify path with action ' +
      JSON.stringify(d.action) + '. Only clear-and-notify authorises a send. Refusing.'
    );
  }
  return {
    json: {
      contact_id,
      contactId: Number(contact_id),
      ht_timeout_notice: d.ht_timeout_notice,
      action: d.action,
      age_ms: d.age_ms === undefined ? null : d.age_ms,
      flag_raw: d.flag_raw === undefined ? null : d.flag_raw,
    },
    pairedItem: { item: i },
  };
});
